/* ---- warps ----
 * x,y is the cell in this map; map/warp say where it leads (map = -1:
 * the destination is not part of this build, so the door is shut).
 * kind 0 = door: warps when the step onto it ends, and the player is
 * pushed one cell out of the doorway on arrival; kind 1 = warp carpet:
 * fires while standing on it facing `dir` (an ow/dir.h direction);
 * kind 2 = everything else that warps (stairs, cave mouths, panels). */
enum { PC_WARP_DOOR, PC_WARP_CARPET, PC_WARP_STEP };
typedef struct {
    uint8_t x, y;
    int8_t map;                /* index into pc_maps, -1 = not in this build */
    uint8_t warp;              /* 1-based event number in the destination */
    uint8_t kind;
    uint8_t dir;               /* carpet direction that triggers it */
} PcWarp;

/* ---- connections ----
 * A shared edge, not a door: walking into the edge cell of this map
 * puts the player on the opposite edge of `map`, shifted `offset`
 * blocks along it (the original's strip offsets, -2 cells per block).
 * `dir` is the ow/dir.h direction you walk to leave this map;
 * map = -1 means the other side is not in this build, so the edge
 * stays solid. */
typedef struct {
    uint8_t dir;
    int8_t map;
    int8_t offset;
} PcConnection;

/* ---- object events: pixel coords on the 16px grid ----
 * dir: 0 down, 1 up, 2 left, 3 right; anim: 0 stand, 1 spin ccw,
 * 2 spin cw, 3 spin randomly (in place). */
typedef struct {
    uint16_t x, y;
    uint8_t sprite;
    uint8_t dir;
    uint8_t anim;
    uint8_t move;              /* SPRITEMOVEDATA_*, the original's number */
    int16_t text;              /* index into pc_texts, -1 = none */
    uint16_t script;           /* offset in the map's script blob, $ffff = none */
} PcObject;

typedef struct {
    const char *name;
    uint8_t w, h;               /* size in blocks (32x32 px) */
    const uint8_t *blocks;
    uint8_t tileset;            /* index into pc_tilesets */
    const PcObject *objects;
    uint8_t object_count;
    const PcWarp *warps;
    uint8_t warp_count;
    uint8_t pal;                /* 0 = bg_pal (outdoor), 1 = bg_pal_indoor */
    uint8_t spawn_x, spawn_y;   /* the game's respawn point, 0 = none */
    const PcConnection *conns;
    uint8_t conn_count;
} PcMapDef;

